  1831	static int process_base_block(struct archive_read* a,
  1832	        struct archive_entry* entry)
  1833	{
  1834	    struct rar5* rar = get_context(a);
  1835	    uint32_t hdr_crc, computed_crc;
  1836	    size_t raw_hdr_size = 0, hdr_size_len, hdr_size;
  1837	    size_t header_id = 0;
  1838	    size_t header_flags = 0;
  1839	    const uint8_t* p;
  1840	    int ret;
  1841	
  1842	    /* Skip any unprocessed data for this file. */
  1843	    if(rar->file.bytes_remaining) {
  1844	        ret = rar5_read_data_skip(a);
  1845	        if(ret != ARCHIVE_OK) {
  1846	            return ret;
  1847	        }
  1848	    }
  1849	
  1850	    /* Read the expected CRC32 checksum. */
  1851	    if(!read_u32(a, &hdr_crc)) {
  1852	        return ARCHIVE_EOF;
  1853	    }
  1854	
  1855	    /* Read header size. */
  1856	    if(!read_var_sized(a, &raw_hdr_size, &hdr_size_len)) {
  1857	        return ARCHIVE_EOF;
  1858	    }
  1859	
  1860	    /* Sanity check, maximum header size for RAR5 is 2MB. */
  1861	    if(raw_hdr_size > (2 * 1024 * 1024)) {
  1862	        archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
  1863	                "Base block header is too large");
  1864	
  1865	        return ARCHIVE_FATAL;
  1866	    }
  1867	
  1868	    hdr_size = raw_hdr_size + hdr_size_len;
  1869	
  1870	    /* Read the whole header data into memory, maximum memory use here is
  1871	     * 2MB. */
  1872	    if(!read_ahead(a, hdr_size, &p)) {
  1873	        return ARCHIVE_EOF;
  1874	    }
  1875	
  1876	    /* Verify the CRC32 of the header data. */
  1877	    computed_crc = (uint32_t) crc32(0, p, (int) hdr_size);
  1878	    if(computed_crc != hdr_crc) {
  1879	        archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
  1880	                "Header CRC error");
  1881	
  1882	        return ARCHIVE_FATAL;
  1883	    }
  1884	
  1885	    /* If the checksum is OK, we proceed with parsing. */
  1886	    if(ARCHIVE_OK != consume(a, hdr_size_len)) {
  1887	        return ARCHIVE_EOF;
  1888	    }
  1889	
  1890	    if(!read_var_sized(a, &header_id, NULL))
  1891	        return ARCHIVE_EOF;
  1892	
  1893	    if(!read_var_sized(a, &header_flags, NULL))
  1894	        return ARCHIVE_EOF;
  1895	
  1896	    rar->generic.split_after = (header_flags & HFL_SPLIT_AFTER) > 0;
  1897	    rar->generic.split_before = (header_flags & HFL_SPLIT_BEFORE) > 0;
  1898	    rar->generic.size = (int)hdr_size;
  1899	    rar->generic.last_header_id = (int)header_id;
  1900	    rar->main.endarc = 0;
  1901	
  1902	    /* Those are possible header ids in RARv5. */
  1903	    enum HEADER_TYPE {
  1904	        HEAD_MARK    = 0x00, HEAD_MAIN  = 0x01, HEAD_FILE   = 0x02,
  1905	        HEAD_SERVICE = 0x03, HEAD_CRYPT = 0x04, HEAD_ENDARC = 0x05,
  1906	        HEAD_UNKNOWN = 0xff,
  1907	    };
  1908	
  1909	    switch(header_id) {
  1910	        case HEAD_MAIN:
  1911	            ret = process_head_main(a, rar, entry, header_flags);
  1912	
  1913	            /* Main header doesn't have any files in it, so it's pointless
  1914	             * to return to the caller. Retry to next header, which should be
  1915	             * HEAD_FILE/HEAD_SERVICE. */
  1916	            if(ret == ARCHIVE_OK)
  1917	                return ARCHIVE_RETRY;
  1918	
  1919	            return ret;
  1920	        case HEAD_SERVICE:
  1921	            ret = process_head_service(a, rar, entry, header_flags);
  1922	            return ret;
  1923	        case HEAD_FILE:
  1924	            ret = process_head_file(a, rar, entry, header_flags);
  1925	            return ret;
  1926	        case HEAD_CRYPT:
  1927	            archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
  1928	                    "Encryption is not supported");
  1929	            return ARCHIVE_FATAL;
  1930	        case HEAD_ENDARC:
  1931	            rar->main.endarc = 1;
  1932	
  1933	            /* After encountering an end of file marker, we need to take
  1934	             * into consideration if this archive is continued in another
  1935	             * file (i.e. is it part01.rar: is there a part02.rar?) */
  1936	            if(rar->main.volume) {
  1937	                /* In case there is part02.rar, position the read pointer
  1938	                 * in a proper place, so we can resume parsing. */
  1939	
  1940	                ret = scan_for_signature(a);
  1941	                if(ret == ARCHIVE_FATAL) {
  1942	                    return ARCHIVE_EOF;
  1943	                } else {
  1944	                    rar->vol.expected_vol_no = rar->main.vol_no + 1;
  1945	                    return ARCHIVE_OK;
  1946	                }
  1947	            } else {
  1948	                return ARCHIVE_EOF;
  1949	            }
  1950	        case HEAD_MARK:
  1951	            return ARCHIVE_EOF;
  1952	        default:
  1953	            if((header_flags & HFL_SKIP_IF_UNKNOWN) == 0) {
  1954	                archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
  1955	                        "Header type error");
  1956	                return ARCHIVE_FATAL;
  1957	            } else {
  1958	                /* If the block is marked as 'skip if unknown', do as the flag
  1959	                 * says: skip the block instead on failing on it. */
  1960	                return ARCHIVE_RETRY;
  1961	            }
  1962	    }
  1963	
  1964	#if !defined WIN32
  1965	    // Not reached.
  1966	    archive_set_error(&a->archive, ARCHIVE_ERRNO_PROGRAMMER,
  1967	            "Internal unpacker error");
  1968	    return ARCHIVE_FATAL;
  1969	#endif
  1970	}
