  1972	static int skip_base_block(struct archive_read* a) {
  1973	    int ret;
  1974	    struct rar5* rar = get_context(a);
  1975	
  1976	    /* Create a new local archive_entry structure that will be operated on
  1977	     * by header reader; operations on this archive_entry will be discarded.
  1978	     */
  1979	    struct archive_entry* entry = archive_entry_new();
  1980	    ret = process_base_block(a, entry);
  1981	
  1982	    /* Discard operations on this archive_entry structure. */
  1983	    archive_entry_free(entry);
  1984	
  1985	    if(rar->generic.last_header_id == 2 && rar->generic.split_before > 0)
  1986	        return ARCHIVE_OK;
  1987	
  1988	    if(ret == ARCHIVE_OK)
  1989	        return ARCHIVE_RETRY;
  1990	    else
  1991	        return ret;
  1992	}
